(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx=x+wx1, sy=y+wy1;
  const wx2=Math.sin(sx*0.03-t*0.15)*8+Math.cos(sy*0.025+t*0.2)*6;
  const wy2=Math.cos(sx*0.025+t*0.18)*8+Math.sin(sy*0.03-t*0.22)*6;
  const sx2=sx+wx2, sy2=sy+wy2;
  const cx=240, cy=120;
  const src=[
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*40,0.13,1.8]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d2*f*1.3-t*sp*0.8+0.5); iS2+=Math.sin(d2*f*0.9+t*sp*0.4+2.0);
  }
  const act=aS/8,inh=iS/8,act2=aS2/8,inh2=iS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx2*0.06-sy2*0.05+t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const dist2=Math.sqrt((sx2-cx)**2+(sy2-cy)**2),ang2=Math.atan2(sy2-cy,sx2-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist2*0.06-ang2*2-t*0.9)*0.2+Math.sin(dist*0.03+ang*5-t*2.0)*0.15;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+bg*0.25-spiral*0.5+act*0.3)*1.8);
  const coupled=Math.tanh((r1*0.6+r2*0.4-r1*r2*0.5)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2=Math.tanh((Math.sin(sx2*0.12)*Math.cos(sy2*0.13)+Math.sin(sx2*0.08+t*0.7)*0.4)*1.3)*0.2;
  const detail=(Math.sin(sx2*0.3+t*3)*Math.sin(sy2*0.35-t*2.5))*0.1;
  const blend=coupled*0.6+cell*0.15+cell2*0.1+detail*0.05+r1*0.1;
  const v=blend*0.5+0.5;
  const pal=[
    [5,10,45],[12,40,85],[15,75,120],[18,125,130],[45,165,120],
    [140,190,80],[210,195,55],[230,155,50],[215,105,55],[185,60,60],
    [140,35,65],[85,20,55],[45,12,50],[15,10,45],[5,10,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(coupled*Math.PI)*0.15+Math.abs(detail)*0.3;
  const edge=Math.abs(coupled)>0.65?1.12:1.0;
  const glow=Math.max(0,Math.sin(coupled*Math.PI*2)*0.5)*(1-Math.abs(coupled)*0.3);
  const bR=pal[i][0]+(pal[i+1][0]-pal[i][0])*sf;
  const bG=pal[i][1]+(pal[i+1][1]-pal[i][1])*sf;
  const bB=pal[i][2]+(pal[i+1][2]-pal[i][2])*sf;
  return[
    Math.min(255,(bR*lum*edge+glow*40)|0),
    Math.min(255,(bG*lum*edge+glow*25)|0),
    Math.min(255,(bB*lum*edge+glow*10)|0)
  ];
}
